export enum Country {
  BENIN = 'Bénin',
  CIV = 'Côte d’Ivoire',
  SENEGAL = 'Sénégal',
  TOGO = 'Togo',
  CAMEROUN = 'Cameroun',
  GABON = 'Gabon',
  BURKINA = 'Burkina Faso',
  MALI = 'Mali',
  NIGER = 'Niger',
  GUINEE = 'Guinée',
  CONGO = 'Congo',
  RDC = 'RDC'
}

export const COUNTRIES = Object.values(Country);

export const COMMON_JOBS = [
  'Étudiant / Stagiaire',
  'Comptable',
  'Commercial / Vendeur',
  'Informaticien / Développeur',
  'Agent Administratif',
  'Infirmier / Santé',
  'Enseignant',
  'Chauffeur',
  'Gestionnaire de projet',
  'Ingénieur',
  'Technicien',
  'Hôtellerie / Restauration'
];

import React, { useState, useEffect } from 'react';
import { AppStep, UserData, GeneratedContent, COUNTRIES, COMMON_JOBS, CVTemplate } from './types';
import { generateProfessionalDocuments } from './geminiService';
import { 
  FileText, 
  MapPin, 
  Briefcase, 
  ChevronRight, 
  ChevronLeft, 
  Download, 
  CheckCircle2, 
  CreditCard,
  Smartphone,
  ShieldCheck,
  Zap,
  ArrowRight,
  Loader2,
  HelpCircle,
  Tag,
  Mail,
  MessageSquare,
  Globe,
  Clock,
  History,
  Layout,
  Eye,
  Trash2
} from 'lucide-react';

type PaymentSubStep = 'select' | 'momo_form' | 'processing';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('landing');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [userData, setUserData] = useState<UserData>({
    country: '', job: '', fullName: '', email: '', phone: '', city: '',
    education: '', experience: '', skills: '', bio: ''
  });
  const [generated, setGenerated] = useState<GeneratedContent | null>(null);
  const [history, setHistory] = useState<GeneratedContent[]>([]);
  const [selectedTemplate, setSelectedTemplate] = useState<CVTemplate>('classic');

  // Payment specific state
  const [paymentSubStep, setPaymentSubStep] = useState<PaymentSubStep>('select');
  const [selectedOperator, setSelectedOperator] = useState('');
  const [momoNumber, setMomoNumber] = useState('');

  // Load history on mount
  useEffect(() => {
    const saved = localStorage.getItem('cv_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("History load error", e);
      }
    }
  }, []);

  const saveToHistory = (content: GeneratedContent) => {
    const newHistory = [content, ...history.filter(h => h.id !== content.id)];
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  const deleteFromHistory = (id: string) => {
    const newHistory = history.filter(h => h.id !== id);
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  const updateData = (fields: Partial<UserData>) => {
    setUserData(prev => ({ ...prev, ...fields }));
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await generateProfessionalDocuments(userData);
      const newContent: GeneratedContent = {
        id: Date.now().toString(),
        date: new Date().toLocaleDateString('fr-FR'),
        userData: { ...userData },
        cv: result.cv,
        letter: result.letter,
        paid: false,
        template: selectedTemplate
      };
      setGenerated(newContent);
      saveToHistory(newContent);
      setStep('payment');
      setPaymentSubStep('select');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const startMomoPayment = (operator: string) => {
    setSelectedOperator(operator);
    setMomoNumber(userData.phone);
    setPaymentSubStep('momo_form');
  };

  const processMomoPayment = () => {
    setPaymentSubStep('processing');
    setTimeout(() => {
      if (generated) {
        const paidContent = { ...generated, paid: true };
        setGenerated(paidContent);
        saveToHistory(paidContent);
      }
      setStep('result');
    }, 4000);
  };

  const renderLanding = () => (
    <div className="flex flex-col items-center text-center px-4 py-12 max-w-2xl mx-auto space-y-8">
      <div className="bg-indigo-600 p-4 rounded-2xl shadow-xl shadow-indigo-100">
        <Zap className="w-12 h-12 text-white" />
      </div>
      <div className="space-y-4">
        <h1 className="text-4xl md:text-5xl font-extrabold text-slate-900 tracking-tight">
          Votre CV Pro en <span className="text-indigo-600">5 minutes</span>
        </h1>
        <p className="text-lg text-slate-600 font-medium leading-relaxed">
          Optimisé pour le marché africain. Générez un CV et une lettre de motivation personnalisés avec l'IA.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 w-full py-8">
        <div className="flex flex-col items-center p-4 bg-white rounded-xl shadow-sm border border-slate-100">
          <Smartphone className="w-8 h-8 text-indigo-500 mb-2" />
          <span className="text-sm font-semibold">Mobile First</span>
        </div>
        <div className="flex flex-col items-center p-4 bg-white rounded-xl shadow-sm border border-slate-100">
          <FileText className="w-8 h-8 text-indigo-500 mb-2" />
          <span className="text-sm font-semibold">Génération IA</span>
        </div>
        <div className="flex flex-col items-center p-4 bg-white rounded-xl shadow-sm border border-slate-100">
          <History className="w-8 h-8 text-indigo-500 mb-2" />
          <span className="text-sm font-semibold">Mes Archives</span>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row gap-4 w-full justify-center">
        <button 
          onClick={() => setStep('context')}
          className="bg-indigo-600 text-white px-8 py-5 rounded-2xl text-lg font-bold shadow-lg hover:bg-indigo-700 transition-all active:scale-95 flex items-center justify-center gap-2"
        >
          Démarrer
          <ChevronRight className="w-6 h-6" />
        </button>
        <button 
          onClick={() => setStep('mes-cv')}
          className="bg-white text-slate-700 border-2 border-slate-200 px-8 py-5 rounded-2xl text-lg font-bold hover:bg-slate-50 transition-all active:scale-95 flex items-center justify-center gap-2"
        >
          <History className="w-6 h-6" />
          Mes CV
        </button>
      </div>
    </div>
  );

  const renderStepHeader = (title: string, current: number, total: number) => (
    <div className="w-full bg-white border-b border-slate-200 sticky top-0 z-10 no-print">
      <div className="max-w-xl mx-auto px-4 py-4 flex items-center justify-between">
        <button onClick={() => setStep('landing')} className="p-2 -ml-2 text-slate-500 hover:text-indigo-600">
           <ChevronLeft className="w-6 h-6" />
        </button>
        <div className="text-center">
          <h2 className="text-lg font-bold text-slate-900">{title}</h2>
          <div className="flex gap-1 justify-center mt-1">
            {[1, 2, 3].map(i => (
              <div key={i} className={`h-1 w-8 rounded-full ${i <= current ? 'bg-indigo-600' : 'bg-slate-200'}`} />
            ))}
          </div>
        </div>
        <div className="w-10"></div>
      </div>
    </div>
  );

  const renderContext = () => (
    <div className="max-w-xl mx-auto px-4 py-8 space-y-6">
      {renderStepHeader("Contexte", 1, 3)}
      <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
        <div className="space-y-2">
          <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
            <MapPin className="w-4 h-4" /> Pays de résidence
          </label>
          <select 
            className="w-full bg-white border border-slate-300 rounded-xl px-4 py-4 text-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all appearance-none"
            value={userData.country}
            onChange={(e) => updateData({ country: e.target.value })}
          >
            <option value="">Choisir un pays...</option>
            {COUNTRIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
            <Briefcase className="w-4 h-4" /> Métier ou Poste visé
          </label>
          <input 
            type="text"
            list="jobs"
            placeholder="Ex: Comptable, Développeur..."
            className="w-full bg-white border border-slate-300 rounded-xl px-4 py-4 text-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
            value={userData.job}
            onChange={(e) => updateData({ job: e.target.value })}
          />
          <datalist id="jobs">
            {COMMON_JOBS.map(j => <option key={j} value={j} />)}
          </datalist>
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
            <Layout className="w-4 h-4" /> Modèle de CV
          </label>
          <div className="grid grid-cols-3 gap-3">
            {(['classic', 'modern', 'minimalist'] as CVTemplate[]).map(t => (
              <button 
                key={t}
                onClick={() => setSelectedTemplate(t)}
                className={`p-3 rounded-xl border-2 text-xs font-bold capitalize transition-all ${selectedTemplate === t ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-100 text-slate-500'}`}
              >
                {t}
              </button>
            ))}
          </div>
        </div>

        <button 
          disabled={!userData.country || !userData.job}
          onClick={() => setStep('personal')}
          className="w-full bg-indigo-600 text-white py-5 rounded-2xl text-lg font-bold shadow-lg disabled:opacity-50 disabled:bg-slate-400 transition-all active:scale-95 flex items-center justify-center gap-2"
        >
          Continuer
          <ChevronRight className="w-6 h-6" />
        </button>
      </div>
    </div>
  );

  const renderPersonal = () => (
    <div className="max-w-xl mx-auto px-4 py-8 space-y-6">
      {renderStepHeader("Informations", 2, 3)}
      <div className="space-y-5 animate-in slide-in-from-right-4 duration-300">
        <div className="grid grid-cols-1 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-500 uppercase">Nom Complet</label>
            <input 
              type="text" placeholder="Prénoms & NOM"
              className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500"
              value={userData.fullName} onChange={(e) => updateData({ fullName: e.target.value })}
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-bold text-slate-500 uppercase">Ville</label>
            <input 
              type="text" placeholder="Ex: Cotonou, Abidjan..."
              className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500"
              value={userData.city} onChange={(e) => updateData({ city: e.target.value })}
            />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-500 uppercase">Email</label>
              <input 
                type="email" placeholder="email@exemple.com"
                className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500"
                value={userData.email} onChange={(e) => updateData({ email: e.target.value })}
              />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-bold text-slate-500 uppercase">Téléphone</label>
              <input 
                type="tel" placeholder="+229 ..."
                className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500"
                value={userData.phone} onChange={(e) => updateData({ phone: e.target.value })}
              />
            </div>
          </div>
        </div>

        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-500 uppercase">Bio / Accroche</label>
          <textarea 
            placeholder="En quelques mots, qui êtes-vous ?"
            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 h-24 outline-none focus:ring-2 focus:ring-indigo-500 resize-none"
            value={userData.bio} onChange={(e) => updateData({ bio: e.target.value })}
          />
        </div>

        <div className="flex gap-4">
          <button onClick={() => setStep('context')} className="flex-1 bg-slate-200 text-slate-700 py-4 rounded-xl font-bold">Retour</button>
          <button 
            disabled={!userData.fullName || !userData.email || !userData.city}
            onClick={() => setStep('experience')} 
            className="flex-[2] bg-indigo-600 text-white py-4 rounded-xl font-bold shadow-md disabled:bg-slate-400"
          >Continuer</button>
        </div>
      </div>
    </div>
  );

  const renderExperience = () => (
    <div className="max-w-xl mx-auto px-4 py-8 space-y-6">
      {renderStepHeader("Expériences", 3, 3)}
      <div className="space-y-5 animate-in slide-in-from-right-4 duration-300">
        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-500 uppercase">Études & Diplômes</label>
          <textarea 
            placeholder="Ex: Master en Gestion..."
            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 h-24 outline-none focus:ring-2 focus:ring-indigo-500 resize-none"
            value={userData.education} onChange={(e) => updateData({ education: e.target.value })}
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-500 uppercase">Expériences Professionnelles</label>
          <textarea 
            placeholder="Ex: 2 ans chez MTN..."
            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 h-32 outline-none focus:ring-2 focus:ring-indigo-500 resize-none"
            value={userData.experience} onChange={(e) => updateData({ experience: e.target.value })}
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-bold text-slate-500 uppercase">Compétences</label>
          <input 
            type="text" placeholder="Ex: Excel, Communication..."
            className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500"
            value={userData.skills} onChange={(e) => updateData({ skills: e.target.value })}
          />
        </div>

        {error && <div className="p-4 bg-red-50 text-red-600 rounded-xl text-sm font-medium border border-red-100">{error}</div>}

        <div className="flex gap-4">
          <button onClick={() => setStep('personal')} className="flex-1 bg-slate-200 text-slate-700 py-4 rounded-xl font-bold">Retour</button>
          <button 
            disabled={loading || !userData.education || !userData.experience}
            onClick={handleGenerate} 
            className="flex-[2] bg-indigo-600 text-white py-4 rounded-xl font-bold shadow-md disabled:bg-slate-400 flex items-center justify-center gap-2"
          >
            {loading ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
                Génération...
              </>
            ) : "Générer mon CV"}
          </button>
        </div>
      </div>
    </div>
  );

  const renderCVLayout = (content: GeneratedContent, isPreview: boolean) => {
    const { cv, userData: ud, template } = content;
    const lines = cv.split('\n');
    const displayLines = isPreview ? lines.slice(0, 10) : lines;

    const templateStyles = {
      classic: "font-serif text-slate-900 leading-normal",
      modern: "font-sans text-slate-800 leading-relaxed",
      minimalist: "font-sans text-slate-600 leading-loose uppercase tracking-tight"
    }[template as CVTemplate] || "font-serif";

    return (
      <div className={`w-full bg-white p-8 md:p-12 shadow-inner border border-slate-100 print:shadow-none print:border-none print:p-0 ${templateStyles}`}>
        {/* Header Section */}
        <div className="border-b-2 border-slate-800 pb-4 mb-6">
          <h1 className="text-3xl font-black uppercase">{ud.fullName}</h1>
          <p className="text-indigo-600 font-bold text-xl">{ud.job}</p>
          <div className="flex flex-wrap gap-x-4 gap-y-1 text-sm text-slate-500 mt-2 font-medium">
            <span className="flex items-center gap-1"><MapPin className="w-3 h-3" /> {ud.city}, {ud.country}</span>
            <span className="flex items-center gap-1"><Mail className="w-3 h-3" /> {ud.email}</span>
            <span className="flex items-center gap-1"><Smartphone className="w-3 h-3" /> {ud.phone}</span>
          </div>
        </div>

        {/* Content Section */}
        <div className={`relative ${isPreview ? 'max-h-96 overflow-hidden' : ''}`}>
          <div className="whitespace-pre-wrap text-sm md:text-base prose prose-slate">
            {displayLines.join('\n')}
          </div>
          {isPreview && (
            <div className="absolute inset-x-0 bottom-0 h-40 bg-gradient-to-t from-white via-white/90 to-transparent flex items-end justify-center pb-4">
              <span className="bg-indigo-600 text-white px-4 py-2 rounded-full text-xs font-black shadow-lg flex items-center gap-2">
                <ShieldCheck className="w-4 h-4" /> Document Incomplet - Payer pour voir
              </span>
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderPayment = () => (
    <div className="max-w-4xl mx-auto px-4 py-12 grid grid-cols-1 lg:grid-cols-2 gap-12 animate-in zoom-in-95 duration-300">
      <div className="space-y-6">
        <div className="text-center lg:text-left space-y-2">
