import React, { useState, useEffect, useRef } from 'react';
import { AppStep, UserData, GeneratedContent, COUNTRIES, COMMON_JOBS, CVTemplate } from './types';
import { generateProfessionalDocuments } from './geminiService';
import { 
  FileText, 
  MapPin, 
  Briefcase, 
  ChevronRight, 
  ChevronLeft, 
  Download, 
  CheckCircle2, 
  CreditCard,
  Smartphone,
  ShieldCheck,
  Zap,
  ArrowRight,
  Loader2,
  HelpCircle,
  Tag,
  Mail,
  MessageSquare,
  Globe,
  Clock,
  History,
  Layout,
  Eye,
  Trash2,
  CloudUpload,
  CloudDownload,
  Database,
  RefreshCw
} from 'lucide-react';

type PaymentSubStep = 'select' | 'momo_form' | 'processing';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('landing');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [userData, setUserData] = useState<UserData>({
    country: '', job: '', fullName: '', email: '', phone: '', city: '',
    education: '', experience: '', skills: '', bio: ''
  });
  const [generated, setGenerated] = useState<GeneratedContent | null>(null);
  const [history, setHistory] = useState<GeneratedContent[]>([]);
  const [selectedTemplate, setSelectedTemplate] = useState<CVTemplate>('classic');
  const [isSyncing, setIsSyncing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Payment specific state
  const [paymentSubStep, setPaymentSubStep] = useState<PaymentSubStep>('select');
  const [selectedOperator, setSelectedOperator] = useState('');
  const [momoNumber, setMomoNumber] = useState('');

  // Load history on mount
  useEffect(() => {
    const saved = localStorage.getItem('cv_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("History load error", e);
      }
    }
  }, []);

  const saveToHistory = (content: GeneratedContent) => {
    const newHistory = [content, ...history.filter(h => h.id !== content.id)];
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  const deleteFromHistory = (id: string) => {
    const newHistory = history.filter(h => h.id !== id);
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  // Feature: Data Export (Backup)
  const handleExportData = () => {
    const dataStr = JSON.stringify(history, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
    const exportFileDefaultName = `sauvegarde_cv_express_${new Date().toISOString().slice(0,10)}.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  // Feature: Data Import (Restore)
  const handleImportData = (event: React.ChangeEvent<HTMLInputElement>) => {
    const fileReader = new FileReader();
    if (event.target.files && event.target.files[0]) {
      fileReader.readAsText(event.target.files[0], "UTF-8");
      fileReader.onload = (e) => {
        try {
          const importedData = JSON.parse(e.target?.result as string);
          if (Array.isArray(importedData)) {
            const mergedHistory = [...importedData, ...history].filter((v, i, a) => a.findIndex(t => (t.id === v.id)) === i);
            setHistory(mergedHistory);
            localStorage.setItem('cv_history', JSON.stringify(mergedHistory));
            alert("Sauvegarde restaurée avec succès !");
          }
        } catch (err) {
          alert("Erreur lors de la lecture du fichier de sauvegarde.");
        }
      };
    }
  };

  // Simulated Cloud Sync
  const handleSyncCloud = () => {
    setIsSyncing(true);
    setTimeout(() => {
      setIsSyncing(false);
      alert("Synchronisation terminée. Vos données sont en sécurité sur votre compte (simulé).");
    }, 2000);
  };

  const updateData = (fields: Partial<UserData>) => {
    setUserData(prev => ({ ...prev, ...fields }));
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await generateProfessionalDocuments(userData);
      const newContent: GeneratedContent = {
        id: Date.now().toString(),
        date: new Date().toLocaleDateString('fr-FR'),
        userData: { ...userData },
        cv: result.cv,
        letter: result.letter,
        paid: false,
        template: selectedTemplate
      };
      setGenerated(newContent);
      saveToHistory(newContent);
      setStep('payment');
      setPaymentSubStep('select');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const startMomoPayment = (operator: string) => {
    setSelectedOperator(operator);
    setMomoNumber(userData.phone);
    setPaymentSubStep('momo_form');
  };

  const processMomoPayment = () => {
    setPaymentSubStep('processing');
    setTimeout(() => {
      if (generated) {
        const paidContent = { ...generated, paid: true };
        setGenerated(paidContent);
        saveToHistory(paidContent);
      }
      setStep('result');
    }, 4000);
  };

  const renderLanding = () => (
    <div className="flex flex-col items-center text-center px-4 py-12 max-w-2xl mx-auto space-y-8">
