type PaymentSubStep = 'select' | 'momo_form' | 'processing';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('landing');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [userData, setUserData] = useState<UserData>({
    country: '', job: '', fullName: '', email: '', phone: '', city: '',
    education: '', experience: '', skills: '', bio: ''
  });
  const [generated, setGenerated] = useState<GeneratedContent | null>(null);
  const [history, setHistory] = useState<GeneratedContent[]>([]);
  const [selectedTemplate, setSelectedTemplate] = useState<CVTemplate>('modern');
  const [isSyncing, setIsSyncing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Payment specific state
  const [paymentSubStep, setPaymentSubStep] = useState<PaymentSubStep>('select');
  const [selectedOperator, setSelectedOperator] = useState('');
  const [momoNumber, setMomoNumber] = useState('');

  // Load history on mount
  useEffect(() => {
    const saved = localStorage.getItem('cv_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("History load error", e);
      }
    }
  }, []);

  const saveToHistory = (content: GeneratedContent) => {
    const newHistory = [content, ...history.filter(h => h.id !== content.id)];
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  const deleteFromHistory = (id: string) => {
    const newHistory = history.filter(h => h.id !== id);
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  const handleExportData = () => {
    const dataStr = JSON.stringify(history, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
    const exportFileDefaultName = `sauvegarde_cv_express_${new Date().toISOString().slice(0,10)}.json`;
    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const handleImportData = (event: React.ChangeEvent<HTMLInputElement>) => {
    const fileReader = new FileReader();
    if (event.target.files && event.target.files[0]) {
      fileReader.readAsText(event.target.files[0], "UTF-8");
      fileReader.onload = (e) => {
        try {
          const importedData = JSON.parse(e.target?.result as string);
          if (Array.isArray(importedData)) {
            const mergedHistory = [...importedData, ...history].filter((v, i, a) => a.findIndex(t => (t.id === v.id)) === i);
            setHistory(mergedHistory);
            localStorage.setItem('cv_history', JSON.stringify(mergedHistory));
            alert("Sauvegarde restaurée avec succès !");
          }
        } catch (err) {
          alert("Erreur lors de la lecture du fichier de sauvegarde.");
        }
      };
    }
  };

  const handleSyncCloud = () => {
    setIsSyncing(true);
    setTimeout(() => {
      setIsSyncing(false);
      alert("Synchronisation terminée.");
    }, 2000);
  };

  const handleDownloadText = () => {
    if (!generated) return;
    const content = `CV DE ${generated.userData.fullName.toUpperCase()}\n\n${generated.cv}\n\n-------------------\nLETTRE DE MOTIVATION\n\n${generated.letter}`;
    const element = document.createElement("a");
    const file = new Blob([content], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = `CV_Express_${generated.userData.fullName.replace(/\s+/g, '_')}.txt`;
    document.body.appendChild(element);
    element.click();
  };

  const updateData = (fields: Partial<UserData>) => {
    setUserData(prev => ({ ...prev, ...fields }));
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await generateProfessionalDocuments(userData);
      const newContent: GeneratedContent = {
        id: Date.now().toString(),
        date: new Date().toLocaleDateString('fr-FR'),
        userData: { ...userData },
        cv: result.cv,
        letter: result.letter,
        paid: false,
        template: selectedTemplate
      };
      setGenerated(newContent);
      saveToHistory(newContent);
      setStep('payment');
      setPaymentSubStep('select');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const startMomoPayment = (operator: string) => {
    setSelectedOperator(operator);
    setMomoNumber(userData.phone);
    setPaymentSubStep('momo_form');
  };

  const processMomoPayment = () => {
    setPaymentSubStep('processing');
    setTimeout(() => {
      if (generated) {
        const paidContent = { ...generated, paid: true };
        setGenerated(paidContent);
        saveToHistory(paidContent);
      }
      setStep('result');
    }, 4000);
  };

  const renderLanding = () => (
    <div className="space-y-24 pb-24">
      {/* Hero Section */}
      <div className="flex flex-col items-center text-center px-4 pt-16 max-w-3xl mx-auto space-y-8 animate-in fade-in zoom-in duration-500">
        <div className="relative group">
          <div className="absolute -inset-1 bg-orange-500 rounded-full blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200"></div>
          <img src={LOGO_URL} alt="CV Express Afrique" className="relative w-32 h-32 md:w-40 md:h-40 object-contain rounded-2xl bg-white p-2 shadow-2xl" />
        </div>
        <div className="space-y-4">
          <h1 className="text-4xl md:text-7xl font-black text-slate-900 tracking-tight leading-tight">
            Propulsez votre carrière en <span className="text-orange-500">Afrique</span>
          </h1>
          <p className="text-xl text-slate-600 font-medium leading-relaxed max-w-xl mx-auto">
            Créez un CV et une lettre de motivation d'exception grâce à l'intelligence artificielle, adaptés aux exigences du marché local.
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4 w-full justify-center pt-4">
          <button 
            onClick={() => setStep('context')}
            className="bg-orange-500 text-white px-10 py-5 rounded-2xl text-xl font-black shadow-xl shadow-orange-100 hover:bg-orange-600 transition-all active:scale-95 flex items-center justify-center gap-2"
          >
            Commencer maintenant
            <ChevronRight className="w-6 h-6" />
          </button>
          <button 
            onClick={() => setStep('mes-cv')}
            className="bg-white text-slate-700 border-2 border-slate-200 px-10 py-5 rounded-2xl text-xl font-bold hover:bg-slate-50 transition-all active:scale-95 flex items-center justify-center gap-2"
          >
            Accéder à mes CV
          </button>
        </div>

        <div className="flex items-center justify-center gap-8 pt-4">
          <div className="text-center">
            <p className="text-2xl font-black text-slate-900">+10k</p>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Utilisateurs</p>
          </div>
          <div className="w-px h-8 bg-slate-200"></div>
          <div className="text-center">
            <p className="text-2xl font-black text-slate-900">24/7</p>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Disponibilité</p>
          </div>
          <div className="w-px h-8 bg-slate-200"></div>
          <div className="text-center">
            <p className="text-2xl font-black text-slate-900">100%</p>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">Sécurisé</p>
          </div>
        </div>
      </div>

      {/* Steps Section */}
      <div className="bg-slate-900 py-24 px-6 overflow-hidden relative">
        <div className="absolute top-0 right-0 w-96 h-96 bg-orange-500/10 rounded-full blur-3xl -mr-48 -mt-48"></div>
        <div className="max-w-6xl mx-auto space-y-16 relative z-10">
          <div className="text-center space-y-4">
            <h2 className="text-3xl md:text-5xl font-black text-white tracking-tight">Comment ça marche ?</h2>
            <p className="text-slate-400 font-medium text-lg">Trois étapes simples pour décrocher votre prochain emploi.</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
            {[
              { 
                step: "01", 
                title: "Informations", 
                desc: "Remplissez vos expériences, diplômes et compétences en quelques clics.",
                icon: <FileText className="w-8 h-8 text-orange-500" />
              },
              { 
                step: "02", 
                title: "Optimisation IA", 
                desc: "Notre IA génère un contenu percutant et professionnel adapté à votre secteur.",
                icon: <Zap className="w-8 h-8 text-orange-500" />
              },
              { 
                step: "03", 
                title: "Paiement & Export", 
                desc: "Réglez via Mobile Money et téléchargez votre pack complet en PDF ou texte.",
                icon: <CreditCard className="w-8 h-8 text-orange-500" />
              }
            ].map((item, i) => (
              <div key={i} className="bg-white/5 border border-white/10 p-10 rounded-[2.5rem] relative group hover:bg-white/10 transition-all">
                <span className="absolute top-8 right-10 text-6xl font-black text-white/5 group-hover:text-orange-500/10 transition-colors">{item.step}</span>
                <div className="p-4 bg-orange-500/20 rounded-2xl w-fit mb-6">
                  {item.icon}
                </div>
                <h3 className="text-2xl font-black text-white mb-4">{item.title}</h3>
                <p className="text-slate-400 font-medium leading-relaxed">{item.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Benefits Section */}
      <div className="max-w-6xl mx-auto px-6 space-y-16">
        <div className="flex flex-col md:flex-row items-center gap-16">
          <div className="flex-1 space-y-8">
            <h2 className="text-4xl md:text-5xl font-black text-slate-900 tracking-tight leading-tight">Pourquoi choisir <span className="text-orange-500">CV Express</span> ?</h2>
            <div className="space-y-6">
              {[
                { title: "Adapté au marché local", desc: "Nos modèles respectent les standards de recrutement de plus de 10 pays africains.", icon: <Globe className="w-6 h-6 text-orange-500" /> },
                { title: "Mobile Money Intégré", desc: "Pas de carte bancaire ? Pas de souci. Payez via MTN, Orange, Moov ou Wave.", icon: <Smartphone className="w-6 h-6 text-orange-500" /> },
                { title: "Génération Express", desc: "Obtenez vos documents en moins de 5 minutes chrono.", icon: <Zap className="w-6 h-6 text-orange-500" /> }
              ].map((benefit, i) => (
                <div key={i} className="flex gap-4 items-start">
                  <div className="p-3 bg-orange-50 rounded-xl mt-1">{benefit.icon}</div>
                  <div>
                    <h4 className="font-black text-lg text-slate-900">{benefit.title}</h4>
                    <p className="text-slate-500 font-medium">{benefit.desc}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div className="flex-1 bg-orange-500 rounded-[3rem] p-12 relative overflow-hidden group">
            <div className="absolute inset-0 bg-slate-900/5 group-hover:bg-transparent transition-colors"></div>
            <div className="relative z-10 space-y-6 text-white">
              <Star className="w-12 h-12 fill-white" />
              <p className="text-2xl font-bold leading-relaxed italic">"Grâce à CV Express, j'ai pu postuler avec un dossier professionnel et j'ai décroché mon entretien chez MTN en moins d'une semaine !"</p>
              <div>
                <p className="font-black text-xl">Moussa Diakité</p>
                <p className="font-bold text-orange-100 uppercase tracking-widest text-xs">Comptable - Abidjan</p>
              </div>
            </div>
            <div className="absolute -bottom-12 -right-12 w-48 h-48 bg-white/10 rounded-full blur-3xl"></div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderStepHeader = (title: string, current: number, total: number) => (
    <div className="w-full bg-white border-b border-slate-200 sticky top-0 z-50 no-print">
      <div className="max-w-xl mx-auto px-4 py-4 flex items-center justify-between">
        <button onClick={() => setStep('landing')} className="p-2 -ml-2 text-slate-400 hover:text-orange-500 transition-colors">
           <ChevronLeft className="w-6 h-6" />
        </button>
        <div className="text-center">
          <h2 className="text-lg font-black text-slate-900">{title}</h2>
          <div className="flex gap-1.5 justify-center mt-1.5">
            {[1, 2, 3].map(i => (
              <div key={i} className={`h-1.5 w-10 rounded-full transition-all duration-500 ${i <= current ? 'bg-orange-500' : 'bg-slate-100'}`} />
            ))}
          </div>
        </div>
        <img src={LOGO_URL} className="w-8 h-8 object-contain" alt="Logo" />
      </div>
    </div>
  );

  const renderContext = () => (
    <div className="max-w-xl mx-auto px-4 py-8 space-y-6">
      {renderStepHeader("Étape 1 : Contexte", 1, 3)}
      <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
        <div className="space-y-2">
          <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
            <MapPin className="w-4 h-4 text-orange-500" /> Pays de résidence
          </label>
          <select 
            className="w-full bg-white border-2 border-slate-100 rounded-2xl px-5 py-4 text-lg font-medium focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 outline-none transition-all appearance-none"
            value={userData.country}
            onChange={(e) => updateData({ country: e.target.value })}
          >
            <option value="">Choisir un pays...</option>
            {COUNTRIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
            <Briefcase className="w-4 h-4 text-orange-500" /> Métier ou Poste visé
          </label>
          <input 
            type="text"
            list="jobs"
            placeholder="Ex: Comptable, Développeur..."
            className="w-full bg-white border-2 border-slate-100 rounded-2xl px-5 py-4 text-lg font-medium focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 outline-none transition-all"
            value={userData.job}
            onChange={(e) => updateData({ job: e.target.value })}
          />
          <datalist id="jobs">
            {COMMON_JOBS.map(j => <option key={j} value={j} />)}
          </datalist>
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
            <Layout className="w-4 h-4 text-orange-500" /> Style du document
          </label>
          <div className="grid grid-cols-3 gap-3">
            {(['classic', 'modern', 'minimalist'] as CVTemplate[]).map(t => (
              <button 
                key={t}
                onClick={() => setSelectedTemplate(t)}
                className={`p-4 rounded-2xl border-2 text-xs font-black uppercase tracking-wider transition-all ${selectedTemplate === t ? 'border-orange-500 bg-orange-50 text-orange-600' : 'border-slate-50 bg-slate-50 text-slate-400 hover:bg-slate-100'}`}
              >
                {t}
              </button>
            ))}
          </div>
        </div>

        <button 
          disabled={!userData.country || !userData.job}
          onClick={() => setStep('personal')}
          className="w-full bg-orange-500 text-white py-5 rounded-2xl text-xl font-black shadow-lg shadow-orange-100 disabled:opacity-50 disabled:bg-slate-300 transition-all active:scale-95 flex items-center justify-center gap-2"
        >
          Continuer
          <ChevronRight className="w-6 h-6" />
        </button>
      </div>
    </div>
  );

  const renderPersonal = () => (
    <div className="max-w-xl mx-auto px-4 py-8 space-y-6">
      {renderStepHeader("Étape 2 : Profil", 2, 3)}
      <div className="space-y-5 animate-in slide-in-from-right-4 duration-300">
        <div className="grid grid-cols-1 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Nom Complet</label>
            <input 
              type="text" placeholder="Prénoms & NOM"
              className="w-full bg-white border-2 border-slate-50 rounded-2xl px-5 py-3.5 font-medium outline-none focus:border-orange-500 transition-colors"
              value={userData.fullName} onChange={(e) => updateData({ fullName: e.target.value })}
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Ville</label>
            <input 
              type="text" placeholder="Ex: Cotonou, Abidjan..."
              className="w-full bg-white border-2 border-slate-50 rounded-2xl px-5 py-3.5 font-medium outline-none focus:border-orange-500 transition-colors"
              value={userData.city} onChange={(e) => updateData({ city: e.target.value })}
            />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Email</label>
              <input 
                type="email" placeholder="email@exemple.com"
                className="w-full bg-white border-2 border-slate-50 rounded-2xl px-5 py-3.5 font-medium outline-none focus:border-orange-500 transition-colors"
                value={userData.email} onChange={(e) => updateData({ email: e.target.value })}
              />
            </div>
            <div className="space-y-1">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Téléphone</label>
              <input 
                type="tel" placeholder="+229 ..."
                className="w-full bg-white border-2 border-slate-50 rounded-2xl px-5 py-3.5 font-medium outline-none focus:border-orange-500 transition-colors"
                value={userData.phone} onChange={(e) => updateData({ phone: e.target.value })}
              />
            </div>
          </div>
        </div>

        <div className="space-y-1">
          <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Bio / Accroche</label>
          <textarea 
            placeholder="En quelques mots, qui êtes-vous ?"
            className="w-full bg-white border-2 border-slate-50 rounded-2xl px-5 py-3.5 h-24 font-medium outline-none focus:border-orange-500 transition-colors resize-none"
            value={userData.bio} onChange={(e) => updateData({ bio: e.target.value })}
          />
        </div>

        <div className="flex gap-4 pt-4">
          <button onClick={() => setStep('context')} className="flex-1 bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all">Retour</button>
          <button 
            disabled={!userData.fullName || !userData.email || !userData.city}
            onClick={() => setStep('experience')} 
            className="flex-[2] bg-orange-500 text-white py-4 rounded-2xl font-black shadow-lg shadow-orange-100 disabled:bg-slate-300"
          >Continuer</button>
        </div>
      </div>
    </div>
  );

  const renderExperience = () => (
    <div className="max-w-xl mx-auto px-4 py-8 space-y-6">
      {renderStepHeader("Étape 3 : Parcours", 3, 3)}
      <div className="space-y-5 animate-in slide-in-from-right-4 duration-300">
        <div className="space-y-1">
          <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Études & Diplômes</label>
          <textarea 
            placeholder="Ex: Master en Gestion..."
            className="w-full bg-white border-2 border-slate-50 rounded-2xl px-5 py-3.5 h-24 font-medium outline-none focus:border-orange-500 transition-colors resize-none"
            value={userData.education} onChange={(e) => updateData({ education: e.target.value })}
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Expériences Professionnelles</label>
          <textarea 
            placeholder="Ex: 2 ans chez MTN..."
            className="w-full bg-white border-2 border-slate-50 rounded-2xl px-5 py-3.5 h-32 font-medium outline-none focus:border-orange-500 transition-colors resize-none"
            value={userData.experience} onChange={(e) => updateData({ experience: e.target.value })}
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Compétences</label>
          <input 
            type="text" placeholder="Ex: Excel, Communication..."
            className="w-full bg-white border-2 border-slate-50 rounded-2xl px-5 py-3.5 font-medium outline-none focus:border-orange-500 transition-colors"
            value={userData.skills} onChange={(e) => updateData({ skills: e.target.value })}
          />
        </div>

        {error && <div className="p-4 bg-red-50 text-red-600 rounded-2xl text-sm font-bold border-2 border-red-100">{error}</div>}

        <div className="flex gap-4 pt-4">
          <button onClick={() => setStep('personal')} className="flex-1 bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200">Retour</button>
          <button 
            disabled={loading || !userData.education || !userData.experience}
            onClick={handleGenerate} 
            className="flex-[2] bg-orange-500 text-white py-4 rounded-2xl font-black shadow-lg shadow-orange-100 disabled:bg-slate-300 flex items-center justify-center gap-2"
          >
            {loading ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
                Génération...
              </>
            ) : "Générer mon pack"}
          </button>
        </div>
      </div>
    </div>
  );

  const renderCVLayout = (content: GeneratedContent, isPreview: boolean) => {
    const { cv, userData: ud, template } = content;
    const lines = cv.split('\n');
    const displayLines = isPreview ? lines.slice(0, 10) : lines;

    const templateStyles = {
      classic: "font-serif text-slate-900 leading-normal",
      modern: "font-sans text-slate-800 leading-relaxed",
      minimalist: "font-sans text-slate-500 leading-loose uppercase tracking-wide"
    }[template as CVTemplate] || "font-serif";

    return (
      <div className={`w-full bg-white p-8 md:p-12 shadow-inner border border-slate-100 print:shadow-none print:border-none print:p-0 ${templateStyles}`}>
        {/* Header Section */}
        <div className="border-b-4 border-orange-500 pb-6 mb-8">
          <h1 className="text-4xl font-black uppercase tracking-tighter text-slate-900">{ud.fullName}</h1>
          <p className="text-orange-500 font-black text-2xl uppercase mt-1">{ud.job}</p>
          <div className="flex flex-wrap gap-x-6 gap-y-2 text-sm text-slate-400 mt-4 font-bold">
            <span className="flex items-center gap-2"><MapPin className="w-4 h-4 text-orange-500" /> {ud.city}, {ud.country}</span>
            <span className="flex items-center gap-2"><Mail className="w-4 h-4 text-orange-500" /> {ud.email}</span>
            <span className="flex items-center gap-2"><Smartphone className="w-4 h-4 text-orange-500" /> {ud.phone}</span>
          </div>
        </div>

        {/* Content Section */}
        <div className={`relative ${isPreview ? 'max-h-96 overflow-hidden' : ''}`}>
          <div className="whitespace-pre-wrap text-sm md:text-base prose prose-slate max-w-none">
            {displayLines.join('\n')}
          </div>
          {isPreview && (
            <div className="absolute inset-x-0 bottom-0 h-40 bg-gradient-to-t from-white via-white/95 to-transparent flex items-end justify-center pb-8">
              <span className="bg-orange-500 text-white px-6 py-2.5 rounded-full text-xs font-black shadow-xl flex items-center gap-2 animate-bounce">
                <ShieldCheck className="w-4 h-4" /> Payer 2.000 FCFA pour débloquer
              </span>
            </div>
          )}
        </div>
      </div>
