type PaymentSubStep = 'select' | 'momo_form' | 'processing' | 'success_code';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('landing');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [userData, setUserData] = useState<UserData>({
    country: '', job: '', fullName: '', email: '', phone: '', city: '',
    education: '', experience: '', skills: '', bio: ''
  });
  const [generated, setGenerated] = useState<GeneratedContent | null>(null);
  const [history, setHistory] = useState<GeneratedContent[]>([]);
  const [selectedTemplate, setSelectedTemplate] = useState<CVTemplate>('modern');
  const [isSyncing, setIsSyncing] = useState(false);

  // Code entry state
  const [inputCode, setInputCode] = useState('');
  const [codeError, setCodeError] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Payment specific state
  const [paymentSubStep, setPaymentSubStep] = useState<PaymentSubStep>('select');
  const [selectedOperator, setSelectedOperator] = useState('');
  const [momoNumber, setMomoNumber] = useState('');
  const [tempCode, setTempCode] = useState('');

  // Load history on mount
  useEffect(() => {
    const saved = localStorage.getItem('cv_history');
    if (saved) {
      try {
        setHistory(JSON.parse(saved));
      } catch (e) {
        console.error("History load error", e);
      }
    }
  }, []);

  const saveToHistory = (content: GeneratedContent) => {
    const newHistory = [content, ...history.filter(h => h.id !== content.id)];
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  const deleteFromHistory = (id: string) => {
    const newHistory = history.filter(h => h.id !== id);
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  const handleExportData = () => {
    const dataStr = JSON.stringify(history, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
    const exportFileDefaultName = `sauvegarde_cv_express_${new Date().toISOString().slice(0,10)}.json`;
    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

