const ADMIN_PASS = "Azerty2026@";
const WEEK_IN_MS = 7 * 24 * 60 * 60 * 1000;

type PaymentSubStep = 'select' | 'momo_instructions' | 'submit_ref' | 'waiting_approval';

const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>('landing');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [userData, setUserData] = useState<UserData>({
    country: '', job: '', fullName: '', email: '', phone: '', city: '',
    education: '', experience: '', skills: '', bio: ''
  });
  const [generated, setGenerated] = useState<GeneratedContent | null>(null);
  const [history, setHistory] = useState<GeneratedContent[]>([]);
  const [selectedTemplate, setSelectedTemplate] = useState<CVTemplate>('modern');
  const [isSyncing, setIsSyncing] = useState(false);

  // Admin & Security states
  const [adminPassInput, setAdminPassInput] = useState('');
  const [adminRequests, setAdminRequests] = useState<GeneratedContent[]>([]);
  const [inputCode, setInputCode] = useState('');
  const [codeError, setCodeError] = useState<string | null>(null);

  // Payment states
  const [paymentSubStep, setPaymentSubStep] = useState<PaymentSubStep>('select');
  const [selectedOperator, setSelectedOperator] = useState('');
  const [transRef, setTransRef] = useState('');
  const [paymentPhone, setPaymentPhone] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Synchronisation simulée du localStorage pour le panel Admin
  useEffect(() => {
    const saved = localStorage.getItem('cv_history');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setHistory(parsed);
        setAdminRequests(parsed.filter((r: GeneratedContent) => r.status === 'pending'));
      } catch (e) {
        console.error("History load error", e);
      }
    }
  }, [step]);

  const saveToHistory = (content: GeneratedContent) => {
    const newHistory = [content, ...history.filter(h => h.id !== content.id)];
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
  };

  const updateRequestStatus = (id: string, status: PaymentStatus, code?: string) => {
    const newHistory = history.map(h => {
      if (h.id === id) {
        return { 
          ...h, 
          status, 
          paid: status === 'approved', 
          unlockCode: code || h.unlockCode,
          unlockTimestamp: status === 'approved' ? Date.now() : h.unlockTimestamp
        };
      }
      return h;
    });
    setHistory(newHistory);
    localStorage.setItem('cv_history', JSON.stringify(newHistory));
    setAdminRequests(newHistory.filter(r => r.status === 'pending'));
  };

  const handleDownloadPdf = () => {
    const element = document.getElementById('cv-full-content');
    if (!element || !generated) return;
    const fileName = `CV_Express_${generated.userData.fullName.replace(/\s+/g, '_')}.pdf`;
    // @ts-ignore
    if (typeof html2pdf !== 'undefined') {
      const opt = {
        margin: [10, 10],
        filename: fileName,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };
      // @ts-ignore
      html2pdf().from(element).set(opt).save();
    } else {
      window.print();
    }
  };

  const handleDownloadText = () => {
    if (!generated) return;
    const content = `CV DE ${generated.userData.fullName.toUpperCase()}\n\n${generated.cv}\n\n-------------------\nLETTRE DE MOTIVATION\n\n${generated.letter}`;
    const element = document.createElement("a");
    const file = new Blob([content], {type: 'text/plain'});
    element.href = URL.createObjectURL(file);
    element.download = `CV_Express_${generated.userData.fullName.replace(/\s+/g, '_')}.txt`;
    document.body.appendChild(element);
    element.click();
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await generateProfessionalDocuments(userData);
      const newContent: GeneratedContent = {
        id: Date.now().toString(),
        date: new Date().toLocaleDateString('fr-FR'),
        userData: { ...userData },
        cv: result.cv,
        letter: result.letter,
        paid: false,
        status: 'unpaid',
        template: selectedTemplate
      };
      setGenerated(newContent);
      saveToHistory(newContent);
      setStep('payment');
      setPaymentSubStep('select');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const submitPaymentRef = () => {
    if (!generated) return;
    const updated: GeneratedContent = {
      ...generated,
      status: 'pending',
      transactionRef: transRef,
      paymentPhone: paymentPhone
    };
    setGenerated(updated);
    saveToHistory(updated);
    setPaymentSubStep('waiting_approval');
  };

  const handleAdminLogin = () => {
    if (adminPassInput === ADMIN_PASS) {
      setStep('admin-dashboard');
      setAdminPassInput('');
    } else {
      alert("Mot de passe incorrect.");
    }
  };

  const handleVerifyCode = () => {
    if (!generated) return;
    if (inputCode === generated.unlockCode) {
      const now = Date.now();
      const expiry = (generated.unlockTimestamp || 0) + WEEK_IN_MS;
      if (now < expiry) {
        setStep('result');
      } else {
        setCodeError("Ce code a expiré (validité 7 jours).");
      }
    } else {
      setCodeError("Code incorrect.");
    }
  };

  const getTemplateStyles = (template: CVTemplate) => {
    switch (template) {
      case 'classic': return "font-serif text-slate-900 border-slate-300 accent-slate-800";
      case 'creative': return "font-sans text-orange-900 border-orange-200 accent-orange-500 bg-orange-50/20";
      case 'executive': return "font-serif text-blue-900 border-blue-100 accent-blue-900 bg-slate-50";
      case 'modern': 
      default: return "font-sans text-slate-800 border-slate-100 accent-blue-600";
    }
  };

  const renderCVLayout = (content: GeneratedContent, isPreview: boolean) => {
    const { cv, userData: ud, template } = content;
    const lines = cv.split('\n');
    const displayLines = isPreview ? lines.slice(0, 10) : lines;
    const themeClass = getTemplateStyles(template);

    return (
      <div className={`w-full p-8 md:p-12 shadow-inner border transition-all ${themeClass}`}>
        <div className="border-b-4 border-current pb-6 mb-8">
          <h1 className="text-4xl font-black uppercase tracking-tighter">{ud.fullName}</h1>
          <p className="text-xl font-bold uppercase mt-1 opacity-80">{ud.job}</p>
          <div className="flex flex-wrap gap-x-6 gap-y-2 text-sm mt-4 font-semibold opacity-60">
            <span className="flex items-center gap-2"><MapPin className="w-4 h-4" /> {ud.city}, {ud.country}</span>
            <span className="flex items-center gap-2"><Mail className="w-4 h-4" /> {ud.email}</span>
            <span className="flex items-center gap-2"><Smartphone className="w-4 h-4" /> {ud.phone}</span>
          </div>
        </div>
        <div className={`relative ${isPreview ? 'max-h-96 overflow-hidden' : ''}`}>
          <div className="whitespace-pre-wrap text-sm md:text-base prose max-w-none leading-relaxed">
            {displayLines.join('\n')}
          </div>
          {isPreview && (
            <div className="absolute inset-x-0 bottom-0 h-40 bg-gradient-to-t from-white via-white/95 to-transparent flex items-end justify-center pb-8">
              <span className="bg-slate-900 text-white px-6 py-2.5 rounded-full text-xs font-black shadow-xl flex items-center gap-2 animate-bounce">
                <Lock className="w-4 h-4" /> Payer 2.000 FCFA pour débloquer
              </span>
            </div>
          )}
        </div>
      </div>
    );
  };

  const renderAdminDashboard = () => (
    <div className="max-w-6xl mx-auto px-4 py-12 space-y-8 animate-in fade-in duration-500">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-4xl font-black text-slate-900 flex items-center gap-3">
            <ShieldAlert className="w-10 h-10 text-orange-500" /> Panel Administrateur
          </h2>
          <p className="text-slate-500 font-medium">Gestion des demandes de déblocage CV Express.</p>
        </div>
        <button onClick={() => setStep('landing')} className="flex items-center gap-2 text-slate-400 hover:text-red-500 font-black uppercase text-xs transition-colors">
          <LogOut className="w-5 h-5" /> Déconnexion
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <p className="text-xs font-black text-slate-400 uppercase tracking-widest">En attente</p>
          <p className="text-4xl font-black text-orange-500">{adminRequests.length}</p>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Total Archivé</p>
          <p className="text-4xl font-black text-slate-900">{history.length}</p>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-100">
            <tr>
              <th className="px-8 py-5">Candidat</th>
              <th className="px-8 py-5">Référence / Tél Paiement</th>
              <th className="px-8 py-5">Date</th>
              <th className="px-8 py-5 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {adminRequests.length === 0 ? (
              <tr><td colSpan={4} className="px-8 py-20 text-center text-slate-300 font-bold">Aucune demande en attente.</td></tr>
            ) : adminRequests.map(req => (
              <tr key={req.id} className="hover:bg-slate-50/50 transition-colors">
                <td className="px-8 py-6">
                  <p className="font-black text-slate-900">{req.userData.fullName}</p>
                  <p className="text-xs text-orange-500 font-bold">{req.userData.job}</p>
                </td>
                <td className="px-8 py-6">
                  <p className="font-mono text-sm font-black text-slate-700">{req.transactionRef || 'N/A'}</p>
                  <p className="text-xs text-slate-400 font-bold">{req.paymentPhone || 'N/A'}</p>
                </td>
                <td className="px-8 py-6 text-sm text-slate-400 font-medium">{req.date}</td>
                <td className="px-8 py-6 text-right space-x-2">
                  <button 
                    onClick={() => {
                      const code = Math.random().toString(36).substring(2, 8).toUpperCase();
                      updateRequestStatus(req.id, 'approved', code);
                    }}
                    className="p-3 bg-emerald-500 text-white rounded-xl hover:bg-emerald-600 transition-all shadow-lg shadow-emerald-100"
                    title="Approuver"
                  >
                    <CheckCircle className="w-5 h-5" />
                  </button>
                  <button 
                    onClick={() => updateRequestStatus(req.id, 'rejected')}
                    className="p-3 bg-red-500 text-white rounded-xl hover:bg-red-600 transition-all shadow-lg shadow-red-100"
                    title="Rejeter"
                  >
                    <XCircle className="w-5 h-5" />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  const renderPayment = () => (
    <div className="max-w-5xl mx-auto px-4 py-12 grid grid-cols-1 lg:grid-cols-2 gap-12">
      <div className="space-y-6">
        <div className="text-center lg:text-left space-y-2">
          <div className="inline-flex items-center justify-center w-12 h-12 bg-orange-100 text-orange-600 rounded-full mb-2">
            <Eye className="w-6 h-6" />
          </div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Vérifiez votre pack</h2>
          <p className="text-slate-500 font-medium italic">Le pack complet (CV + Lettre) sera débloqué après validation.</p>
        </div>
        {generated && renderCVLayout(generated, true)}
      </div>

      <div className="space-y-6 h-fit lg:sticky lg:top-24">
        {paymentSubStep === 'select' && (
          <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 space-y-6">
            <div className="flex justify-between items-center pb-6 border-b border-slate-100">
              <div>
                <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Prix du Pack Pro</p>
                <p className="text-5xl font-black text-slate-900">2.000 <span className="text-xl">FCFA</span></p>
              </div>
              <img src={LOGO_URL} className="w-16 h-16 object-contain" alt="Logo" />
            </div>
            <div className="space-y-4">
              <p className="text-sm font-black text-slate-700 uppercase tracking-wide">Payer par Mobile Money :</p>
              <div className="grid grid-cols-2 gap-3">
                {['MTN MoMo', 'Orange Money', 'Moov Money', 'Wave'].map(op => (
                  <button key={op} onClick={() => { setSelectedOperator(op); setPaymentSubStep('momo_instructions'); }} className="flex flex-col items-center gap-2 p-5 border-2 border-slate-50 rounded-2xl hover:border-orange-500 hover:bg-orange-50 transition-all group">
                    <span className="text-xs font-black text-slate-700 group-hover:text-orange-600">{op}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {paymentSubStep === 'momo_instructions' && (
          <div className="bg-white rounded-[2.5rem] p-10 shadow-2xl border border-slate-100 space-y-8 animate-in zoom-in-95 duration-300">
            <button onClick={() => setPaymentSubStep('select')} className="flex items-center gap-2 text-slate-400 text-xs font-black hover:text-slate-600"><ChevronLeft className="w-4 h-4"/> Retour</button>
            <div className="space-y-4 text-center">
               <h3 className="text-2xl font-black text-slate-900">Paiement Manuel {selectedOperator}</h3>
               <p className="text-slate-500 font-medium">Envoyez exactement <span className="font-black text-slate-900">2.000 FCFA</span> au numéro suivant :</p>
               <div className="bg-slate-900 text-white p-6 rounded-3xl flex items-center justify-between group cursor-pointer relative overflow-hidden" onClick={() => { navigator.clipboard.writeText(ADMIN_PHONE); alert("Numéro copié !"); }}>
                  <div className="relative z-10">
                    <p className="text-[10px] font-black text-orange-500 uppercase tracking-[0.2em] mb-1">Destinataire</p>
                    <p className="text-3xl font-black tracking-widest">{ADMIN_PHONE}</p>
                  </div>
                  <Copy className="w-8 h-8 opacity-20 group-hover:opacity-100 transition-opacity" />
                  <div className="absolute inset-0 bg-orange-500/10 scale-x-0 group-hover:scale-x-100 transition-transform origin-left"></div>
               </div>
            </div>
            <div className="bg-orange-50 p-6 rounded-2xl border border-orange-100">
               <p className="text-xs font-bold text-orange-700 leading-relaxed">Une fois le transfert effectué, cliquez sur le bouton ci-dessous pour nous envoyer votre référence de transaction.</p>
            </div>
            <button onClick={() => setPaymentSubStep('submit_ref')} className="w-full bg-orange-500 text-white py-5 rounded-2xl text-xl font-black shadow-lg hover:bg-orange-600 transition-all">J'ai effectué le dépôt</button>
          </div>
        )}

        {paymentSubStep === 'submit_ref' && (
          <div className="bg-white rounded-[2.5rem] p-10 shadow-2xl border border-slate-100 space-y-6 animate-in slide-in-from-right-4 duration-300">
             <h3 className="text-2xl font-black text-slate-900">Confirmation d'envoi</h3>
             <div className="space-y-4">
                <div className="space-y-1">
                   <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Votre numéro de téléphone (Paiement)</label>
                   <input type="tel" className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-4 text-lg font-black outline-none focus:border-orange-500 transition-colors" placeholder="Ex: 0102030405" value={paymentPhone} onChange={(e) => setPaymentPhone(e.target.value)} />
                </div>
                <div className="space-y-1">
                   <label className="text-xs font-black text-slate-400 uppercase tracking-widest">ID / Réf de la transaction</label>
                   <input type="text" className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-5 py-4 text-lg font-black outline-none focus:border-orange-500 transition-colors" placeholder="Ex: TXN12345678" value={transRef} onChange={(e) => setTransRef(e.target.value)} />
                </div>
                <button 
                   disabled={!paymentPhone || !transRef}
                   onClick={submitPaymentRef} 
                   className="w-full bg-orange-500 text-white py-5 rounded-2xl text-xl font-black shadow-lg disabled:opacity-50 disabled:bg-slate-300"
                >Soumettre pour validation</button>
             </div>
          </div>
        )}

        {paymentSubStep === 'waiting_approval' && (
           <div className="bg-white rounded-[2.5rem] p-12 shadow-2xl border border-slate-100 flex flex-col items-center text-center space-y-6">
              <div className="w-20 h-20 bg-orange-100 text-orange-500 rounded-full flex items-center justify-center animate-pulse">
                <Clock className="w-10 h-10" />
              </div>
              <h3 className="text-2xl font-black text-slate-900">Validation en cours</h3>
              <p className="text-slate-500 font-medium leading-relaxed">Nos administrateurs vérifient votre paiement. Cela prend généralement entre <span className="font-black text-slate-900">5 à 15 minutes</span>.</p>
              <div className="bg-slate-50 p-4 rounded-xl w-full text-xs font-bold text-slate-400 italic">Vous pouvez fermer cette page et revenir plus tard dans "Mes Archives" pour vérifier le statut.</div>
              <button onClick={() => setStep('mes-cv')} className="w-full py-4 border-2 border-slate-100 rounded-2xl font-black text-slate-400 hover:text-orange-500 transition-all">Voir mes archives</button>
           </div>
        )}
      </div>
    </div>
  );

  const renderUnlock = () => (
    <div className="max-w-xl mx-auto px-4 py-16 space-y-8 animate-in zoom-in duration-300">
      <div className="text-center space-y-4">
        <div className="w-20 h-20 bg-orange-100 text-orange-600 rounded-full flex items-center justify-center mx-auto shadow-inner">
          <Lock className="w-10 h-10" />
        </div>
        <h2 className="text-3xl font-black text-slate-900 tracking-tight">Accès sécurisé</h2>
        <p className="text-slate-500 font-medium italic">Saisissez votre code unique de déblocage.</p>
      </div>
      <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl border border-slate-100 space-y-6">
        <div className="space-y-2">
          <label className="text-xs font-black text-slate-400 uppercase tracking-widest">Code de déblocage</label>
          <input 
            type="text" 
            placeholder="ABC123" 
            className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-5 text-3xl font-black text-center text-slate-900 uppercase tracking-[0.2em] outline-none focus:border-orange-500 transition-colors"
            value={inputCode}
            onChange={(e) => { setInputCode(e.target.value.toUpperCase()); setCodeError(null); }}
          />
          {codeError && <div className="flex items-center gap-2 text-red-500 text-xs font-black"><AlertCircle className="w-4 h-4" /> {codeError}</div>}
        </div>
        <button onClick={handleVerifyCode} className="w-full bg-orange-500 text-white py-5 rounded-2xl text-xl font-black shadow-lg hover:bg-orange-600 transition-all active:scale-95 flex items-center justify-center gap-3">
          <Unlock className="w-6 h-6" /> Débloquer maintenant
        </button>
      </div>
      <button onClick={() => setStep('mes-cv')} className="block mx-auto text-slate-400 font-bold hover:text-orange-500 transition-colors">Retour aux archives</button>
    </div>
  );

  const renderLanding = () => (
    <div className="space-y-24 pb-24">
      {/* Hero Section */}
      <div className="flex flex-col items-center text-center px-4 pt-16 max-w-3xl mx-auto space-y-8 animate-in fade-in zoom-in duration-500">
        <div className="relative group">
          <div className="absolute -inset-1 bg-orange-500 rounded-full blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200"></div>
          <img src={LOGO_URL} alt="CV Express Afrique" className="relative w-32 h-32 md:w-40 md:h-40 object-contain rounded-2xl bg-white p-2 shadow-2xl" />
        </div>
        <div className="space-y-4">
          <h1 className="text-4xl md:text-7xl font-black text-slate-900 tracking-tight leading-tight">
            Propulsez votre carrière en <span className="text-orange-500">Afrique</span>
          </h1>
          <p className="text-xl text-slate-600 font-medium leading-relaxed max-w-xl mx-auto">
            Créez un CV d'exception grâce à l'IA, validé par nos experts. Paiement sécurisé par Mobile Money.
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4 w-full justify-center pt-4">
          <button onClick={() => setStep('context')} className="bg-orange-500 text-white px-10 py-5 rounded-2xl text-xl font-black shadow-xl shadow-orange-100 hover:bg-orange-600 transition-all active:scale-95 flex items-center justify-center gap-2">
            Créer mon Pack Pro <ChevronRight className="w-6 h-6" />
          </button>
          <button onClick={() => setStep('mes-cv')} className="bg-white text-slate-700 border-2 border-slate-200 px-10 py-5 rounded-2xl text-xl font-bold hover:bg-slate-50 transition-all active:scale-95 flex items-center justify-center gap-2">
            Mes documents
          </button>
        </div>
      </div>

      {/* Avis Section */}
      <div className="max-w-6xl mx-auto px-6 grid grid-cols-1 md:grid-cols-3 gap-8">
        {[
          { name: "Amadou K.", role: "Ingénieur", city: "Dakar", text: "Processus de validation rapide. Le CV est parfait.", stars: 5 },
          { name: "Cynthia E.", role: "Marketeuse", city: "Abidjan", text: "Top ! La lettre de motivation m'a beaucoup aidée.", stars: 5 },
          { name: "Patrice M.", role: "Logistique", city: "Douala", text: "Service sérieux, le code arrive bien après le SMS.", stars: 4 }
        ].map((rev, i) => (
          <div key={i} className="bg-white p-8 rounded-3xl border border-slate-100 shadow-sm space-y-4 hover:shadow-md transition-shadow">
            <div className="flex gap-1">{[...Array(rev.stars)].map((_, j) => <Star key={j} className="w-4 h-4 fill-orange-500 text-orange-500" />)}</div>
            <p className="text-slate-600 font-medium italic italic">"{rev.text}"</p>
            <div className="flex items-center gap-3 pt-2">
              <div className="w-10 h-10 bg-orange-100 rounded-full flex items-center justify-center font-black text-orange-600">{rev.name[0]}</div>
              <div>
                <p className="font-black text-sm text-slate-900">{rev.name}</p>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{rev.role} • {rev.city}</p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const renderContext = () => (
    <div className="max-w-xl mx-auto px-4 py-8 space-y-6">
      {renderStepHeader("Étape 1 : Style & Pays", 1, 3)}
      <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
        <div className="space-y-2">
          <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
            <MapPin className="w-4 h-4 text-orange-500" /> Pays de résidence
          </label>
          <select className="w-full bg-white border-2 border-slate-100 rounded-2xl px-5 py-4 text-lg font-medium focus:border-orange-500 outline-none transition-all appearance-none" value={userData.country} onChange={(e) => updateData({ country: e.target.value })}>
            <option value="">Choisir un pays...</option>
            {COUNTRIES.map(c => <option key={c} value={c}>{c}</option>)}
