    }
    const savedEmail = localStorage.getItem('cv_user_email');
    if (savedEmail) {
      setUserEmail(savedEmail);
      setIsLoggedIn(true);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('cv_history', JSON.stringify(history));
    setAdminRequests(history.filter(r => r.status === 'pending'));
