    localStorage.removeItem('cv_user_email');
    setIsLoggedIn(false);
    setUserEmail('');
    setUserPass('');
    setStep('landing');
  };

  const saveToHistory = (content: GeneratedContent) => {
    setHistory(prev => [
      { ...content, ownerEmail: userEmail },
      ...prev.filter(h => h.id !== content.id)
    ]);
  };

  const deleteFromHistory = (id: string) => {
